    intervalMs: 8000,     // [V63] 9000→8000 — 서브틱 간격 단축, 같은 시간창에 1틱 더 (청산 반응속도↑)
    maxSymbols: 50,       // 폴링 대상 상한 (1 배치=1 subrequest)
