          const mkLines = Object.keys(byMkt).sort(function (a, b) { return byMkt[b] - byMkt[a]; }).map(function (m) { return "  · " + mkNm[m] + " " + (byMkt[m] / total * 100).toFixed(0) + "%"; });
          const hhi = rows.reduce(function (s, r) { return s + Math.pow(r.val / total, 2); }, 0);
