          Object.keys(agg).sort(function (a, b) { return (agg[b].sum / agg[b].n) - (agg[a].sum / agg[a].n); }).forEach(function (m) { const a = agg[m]; L.push("- " + (mkNm[m] || m) + ": 승률 " + (a.w / a.n * 100).toFixed(0) + "% · 평균 " + (a.sum / a.n >= 0 ? "+" : "") + (a.sum / a.n).toFixed(1) + "% (" + a.n + "건)"); });
